const listAccountingBookScopes = `-- name: ListAccountingBookScopes :many
SELECT user_id, query_access, operate_access
FROM acc_book_user_scopes
WHERE book_id = $1
ORDER BY user_id
`

type ListAccountingBookScopesRow struct {
	UserID        string `db:"user_id" json:"user_id"`
	QueryAccess   bool   `db:"query_access" json:"query_access"`
	OperateAccess bool   `db:"operate_access" json:"operate_access"`
}

func (q *Queries) ListAccountingBookScopes(ctx context.Context, bookID string) ([]ListAccountingBookScopesRow, error) {
	rows, err := q.db.Query(ctx, listAccountingBookScopes, bookID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAccountingBookScopesRow{}
	for rows.Next() {
		var i ListAccountingBookScopesRow
		if err := rows.Scan(&i.UserID, &i.QueryAccess, &i.OperateAccess); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listAccountingBooks = `-- name: ListAccountingBooks :many
SELECT b.id, b.code, b.name, b.description,
       to_char(b.start_month, 'YYYY-MM') AS start_month,
       b.base_currency, b.control_book, b.subject_template,
       b.revision, count(*) OVER() AS total
FROM acc_books b
JOIN acc_book_user_scopes s ON s.book_id = b.id
WHERE s.user_id = $1
  AND s.query_access
  AND (
    $2::text = ''
    OR b.code ILIKE '%' || $2 || '%'
    OR b.name ILIKE '%' || $2 || '%'
  )
ORDER BY b.control_book DESC, b.code, b.id
OFFSET $3 LIMIT $4
`

